                self._v = 1

            @wrap_prop(Ctx())
            @property
            def value(self):
                return self._v

            @value.deleter
            def value(self):
                log.append("del")
                del self._v

        a = A()
        del a.value
        assert log == ["enter", "del", "exit"]
        assert not hasattr(a, "_v")

