            def value(self):
                counter[0] += 1
                return counter[0]

        a, b = Foo(), Foo()
        assert a.value == 1
        assert a.value == 1
        assert b.value == 2
        assert b.value == 2
        assert counter[0] == 2

    def test_uses_fget_name_as_cache_key(self):
        class Foo:
            @cached_property
            def myname(self):
