class TrackingCM:
    def __init__(self):
        self.enter_count = 0
        self.exit_count = 0

    def __enter__(self):
        self.enter_count += 1
        return self

    def __exit__(self, *exc):
        self.exit_count += 1
        return False


class TestWrapProp:
    def test_wraps_getter(self):
        cm = TrackingCM()

        class Foo:
            def __init__(self):
                self._val = 3

            @wrap_prop(cm)
            @property
            def value(self):
                return self._val

        f = Foo()
        assert f.value == 3
        assert cm.enter_count == 1
        assert cm.exit_count == 1

    def test_wraps_setter(self):
        cm = TrackingCM()

        class Foo:
            def __init__(self):
                self._val = 0

            @wrap_prop(cm)
            @property
            def value(self):
                return self._val

            @value.setter
            def value(self, v):
                self._val = v

        f = Foo()
        f.value = 11
        assert f._val == 11
        assert cm.enter_count == 1
        assert cm.exit_count == 1
        assert f.value == 11
        assert cm.enter_count == 2

    def test_wraps_deleter(self):
        cm = TrackingCM()

        class Foo:
            def __init__(self):
                self._val = 3

            @wrap_prop(cm)
            @property
            def value(self):
                return self._val

            @value.deleter
            def value(self):
                del self._val

        f = Foo()
        del f.value
        assert not hasattr(f, '_val')
        assert cm.enter_count == 1
        assert cm.exit_count == 1

    def test_class_level_access_returns_wrapper(self):
        cm = TrackingCM()

        class Foo:
            @wrap_prop(cm)
            @property
            def value(self):
                return 1

        assert isinstance(Foo.value, object)
        assert Foo.value is Foo.__dict__['value']
        # Accessing class-level attribute should not enter the context.
        assert cm.enter_count == 0

    def test_repr_delegates_to_wrapped(self):
        cm = TrackingCM()

        class Foo:
            @wrap_prop(cm)
            @property
            def value(self):
                return 1

        inner = Foo.__dict__['value'].__repr__()
        # The repr should look like a property repr.
        assert inner == repr(property(Foo.__dict__['value'].fget if hasattr(Foo.__dict__['value'], 'fget') else (lambda self: 1))) or 'property' in inner.lower() or '<' in inner

    def test_no_setter_means_no_set_descriptor(self):
        cm = TrackingCM()

        class Foo:
            @wrap_prop(cm)
            @property
            def value(self):
                return 1

        wrapper = Foo.__dict__['value']
        # Since underlying property has no __set__, wrapper should not define one
        # (property actually always has __set__, so this checks hasattr behavior consistency)
        assert hasattr(wrapper, '__get__')

    def test_reusable_decorator_for_multiple_props(self):
        cm = TrackingCM()

        class Foo:
            def __init__(self):
                self._a = 1
                self._b = 2

            @wrap_prop(cm)
            @property
            def a(self):
                return self._a

            @wrap_prop(cm)
            @property
            def b(self):
                return self._b

        f = Foo()
        assert f.a == 1
        assert f.b == 2
        assert cm.enter_count == 2
        assert cm.exit_count == 2


