def test_lazy_object_init_and_setup():
    calls = []

    class Target:
        def __init__(self):
            calls.append(1)
            self.value = 5

        def method(self):
            return 'm'

    class Inner:
        value = 10

        def method(self):
            return 'm'

    def make():
        calls.append('made')
        return Inner()

    lazy = LazyObject(make)
    assert lazy.__dict__ == {'_init': make}

    assert lazy.value == 10
    assert calls == ['made']
    assert lazy.method() == 'm'


